INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"b4824b41-524f-431a-8f8b-77bdd35c6f01"}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 1, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0185","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0189","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0191","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0193","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0196","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0198","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0199","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0276"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 2, $s$text$s$, $s${"html":"Stepping Back in Time (and Loving Every Minute!) 🕰️ \n\nOur Plymouth adventure kicked off on Water Street, the perfect gateway to this historic town. You’ll find convenient parking 🅿️ right along the street or, if you prefer, in the lot behind the information center ℹ️ just across the road. \n\nI highly recommend making your first stop the information center. It's packed with maps 🗺️, brochures, and helpful staff who can offer great insights to make your visit even better. Plus, it's a super convenient spot to find clean public restrooms 🚻 before you start your explorations! \n\nAs we stepped out, we were immediately struck by the breathtaking views of the harbor ⚓. The sparkling water and boats 🛥️ created such a picturesque scene. We soaked it all in before making our way toward Fishermen's Park. Here, you'll find a tranquil spot to reflect and often see local artists 🎨 or fishermen 🎣 going about their day – it’s a lovely view, so don't skip it. Planning to dine on the wharf? 🍽️ A little 💥insider tip: if you're visiting on a busy summer day, it’s a smart move to book a table in advance at one of the many restaurants. They fill up fast, and you don't want to miss out on those waterfront views!\nContinuing our stroll along Water Street, our next destination was the iconic Mayflower II ⛵.  Along the way, we stumbled upon a delightful display of artist-painted beach chairs 🎨🏖️. I absolutely couldn't resist stopping and sitting on them for a few minutes – they added such a vibrant touch to the historic surroundings. It's those little unexpected gems that make exploring Plymouth so much fun! ✨"}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 3, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0187","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0197"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 4, $s$text$s$, $s${"html":"After soaking in the harbor views and admiring those charming painted beach chairs 🎨🏖️, our journey continued along Water Street, leading us directly to Plymouth's majestic centerpiece: the Mayflower II. This isn't just any old ship; it's a full-scale, crafted replica of the iconic vessel that brought the Pilgrims to these shores in 1620. Stepping aboard, you'll immediately notice the incredible attention to detail. It's designed to give you a profound sense of what the original 17th-century voyage was like."}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 5, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0200","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0203","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0205","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0207","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0208","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0277","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0184"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 6, $s$text$s$, $s${"html":"After our fascinating voyage aboard the Mayflower II, we continued our stroll along Water Street, heading directly towards Plymouth's most iconic landmark: Plymouth Rock! The walk itself is a journey through living history that tells the story of America's beginnings."}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 7, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0213","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0215","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0232","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0233","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0234","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0236"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 8, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0220","html":"Arriving at the Rock, let's be honest: when you first see it, it might not be the massive, towering monument some imagine. But its true significance isn't in its size, it's in its story and symbolism. Nestled beneath an impressive granite. The Rock is widely recognized as the traditional landing place of the Pilgrims in December 1620. While historians debate whether this exact stone was their first point of contact (many believe it was, but there's no definitive proof from the Pilgrims themselves), what is undeniable is its enduring role as a powerful national icon."}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 9, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0216","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0231"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 10, $s$text$s$, $s${"html":"We started our ascent away from the waterfront, climbing towards another of Plymouth's essential historical gems: the famous Plimoth Grist Mill. The way uphill is a beautiful journey through the heart of the town, you will pass the Burial Hill, Plymouth's oldest and most historic cemetery. Dating back to the 17th century, it's the final resting place for many original Pilgrims and their descendants.  🪦🌳\n\nThe Plimoth Grist Mill isn't just a picturesque old building; it's a working replica of a 17th-century water-powered grist mill!"}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 11, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0246","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0247","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0248","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0249","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0256","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0259","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0245","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0236"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 12, $s$text$s$, $s${"html":"After our historical deep dive, we decided to stroll through downtown Plymouth, and it's delightful! It's a fantastic blend of old-world charm and modern convenience. \n\nTown Square is located near Burial Hill and the First Parish Church. You'll find charming shops and historical markers, making it a lovely place to soak in the atmosphere. 🏘️⛪\nWe couldn't resist! We grabbed a delicious ice cream 🍦 and were lucky enough to find a cozy spot that overlooked the sparkling harbor🚶‍♀️🎉"}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 13, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0243","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0244","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0235","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0261","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0263","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0264","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0266","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0267","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0269","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0275","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0273"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 14, $s$text$s$, $s${"html":"After our downtown break, complete with ice cream and those perfect harbor views 🍦⚓, we reluctantly pulled ourselves away and hopped back in the car. Our next destination was the grand finale of our Plymouth journey, and arguably the most immersive experience: Plimoth Patuxet Museums!\n\nJust a short drive from the historic waterfront, this isn't just a museum – it's a living journey with a live demonstration. If you've ever visited Historic Colonial Williamsburg in Virginia, you'll immediately feel a similar magic here. It brings history to life in an incredibly authentic and engaging way! ✨ (💥allow 2-3h)"}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 15, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0279","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0280","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0282"]}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 16, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0283","html":"But wait! On our way from Plimoth Patuxet back to the harbor for dinner, we made one last, absolutely must-stop detour: the incredible National Monument to the Forefathers! 🗽\n\nThis towering granite monument, dedicated in 1889, is an often-overlooked masterpiece. Did you know that it is the largest granite monument in the United States? It symbolizes the ideals the Pilgrims brought with them.  Take a moment to walk around it – it's truly breathtaking! 🤯\nI"}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 17, $s$text$s$, $s${"html":"We returned to the vibrant waterfront for our grand finale: a delicious dinner back at the harbor! We settled into a restaurant right on Fisherman's Wharf, eager to savor some local flavors. 🍽️🦀\n Cheers to history, charm, and unforgettable experiences! 🥂🌊"}$s$::jsonb),
  ($s$07553456-c677-42a3-892b-cd72c5a2ad67$s$, 18, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0284","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0286","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0288","aroundtheworld50s/blog/united-states-massachusetts/1/IMG_0299"]}$s$::jsonb);
